insert into public.equipment_models(name,category,description,specifications,suitable_brew_methods,official_url,source_url,source_type,source_name,last_verified_at,data_confidence,requires_review,image_url,image_source_url,image_usage_status) select 'OREA V4','other','Modular brewer with four different bottoms; bottom and paper selection change the brewing setup.',jsonb_build_object('catalog','{"name_ar": "OREA V4", "description_ar": "قطّارة بوحدات قابلة للتبديل وأربع قواعد مختلفة؛ اختيار القاعدة والورق يغيّر أسلوب التحضير.", "description_en": "Modular brewer with four different bottoms; bottom and paper selection change the brewing setup.", "facts": {"operation": ["يدوي", "Manual"], "capacity": ["حتى كوبين وفق الشركة", "Up to two cups per manufacturer"], "bottoms": ["4: سريعة وكلاسيكية ومفتوحة وأبيكس", "4: Fast, Classic, Open and Apex"], "filter": ["ويف أو مسطح أو سيباريست بحسب الإعداد", "Wave, flat or Sibarist, setup dependent"]}, "schema_version": 1, "evidence": {"url": "https://www.orea.uk/guides-v4", "final_url": "https://www.orea.uk/guides-v4", "title": "GUIDES V4", "checked_at": "2026-10-05T20:24:56.576217+00:00", "sha256": "fd643edaccaf3781e75e7760b52cef892a6630a8ee013f46b667b85097990c0d", "image_url": null}, "extra_sources": []}'::jsonb),array['orea']::text[],'https://www.orea.uk/guides-v4','https://www.orea.uk/guides-v4','official_product_page','GUIDES V4','2026-10-05T20:24:56.576217+00:00'::timestamptz,'official',false,null,'https://www.orea.uk/guides-v4','placeholder_only' where not exists(select 1 from public.equipment_models where name='OREA V4' and category='other');
do $$ begin if (select count(*) from public.equipment_models where not requires_review and specifications->'catalog'->>'schema_version'='1')<66 then raise exception 'reviewed equipment catalog is incomplete';end if;end $$;
commit;
select category,count(*) as models from public.equipment_models where not requires_review group by category order by category;
